import polars as pl

from polars_bloomberg import BQuery

with BQuery(timeout=50000) as con:
    res = []
    for n in range(1, 4):
        tbl = con.bql(f"""
            let(#eps=headline_eps_market(
                    fa_period_offset={n},
                    fa_period_type=A,
                    as_of_date=range('2009-12-31', TODAY(), frq=W)
                    );
            )
            get(#eps)
            for(['SPX Index'])
        """).combine()
        res.append(tbl)
data = pl.concat(res).drop_nulls().sort(by="AS_OF_DATE")
data.head(3)
